int smb2_handle_write(unsigned int xid, struct cifs_io_parms *io_parms, unsigned int *nbytes,
                      struct kvec *iov, int n_vec) {
    struct smb2_write *req = NULL;
    struct smb2_write_response *resp = NULL;
    int rc = 0;
    int i;

    /* Initialize and prepare write request */
    req = cifs_smb2_init(SMB2_WRITE, sizeof(struct smb2_write), 0, 0);
    if (!req) {
        rc = -ENOMEM;
        goto out;
    }

    req->PersistentFileId = io_parms->persistent_fid;
    req->VolatileFileId = io_parms->volatile_fid;
    req->Offset = cpu_to_le64(io_parms->offset);
    req->Length = cpu_to_le32(io_parms->length);
    req->Remaining = cpu_to_le32(0);

    for (i = 0; i < n_vec; i++) {
        req->DataOffset[i] = cpu_to_le16(i * 0x1000);
        memcpy(req->Data[i], iov[i].iov_base, iov[i].iov_len);
    }

    rc = cifs_send_recv(xid, io_parms->tcon, (char *)req, iov, n_vec, 0, (char **)&resp);
    if (rc < 0)
        goto out;

    if (resp->Status != 0) {
        rc = -EIO;
        goto out;
    }

    *nbytes = le32_to_cpu(resp->Count);

out:
    kfree(req);
    return rc;
}

int smb2_handle_write(unsigned int xid, struct cifs_io_parms *io_parms,
                      unsigned int *nbytes, struct kvec *iov, int n_vec)
{
    int rc = 0;
    struct smb2_write_request *req;
    struct smb2_write_response *resp;
    struct TCP_Server_Info *server = io_parms->cfile->server;

    if (!server || !serverCanDoModernOps(server)) {
        return -EIO;
    }

    req = smb2_write_init(server, (unsigned int)CIFSMaxBufSize,
                          io_parms->persistent_fid, io_parms->volatile_fid);
    if (!req)
        return -ENOMEM;

    req->Length = cpu_to_le32(*nbytes);
    req->Offset = cpu_to_le64(io_parms->offset);

    rc = build_kvec(iov, n_vec, req->DataOffset);
    if (rc)
        goto out;

    rc = cifs_send_recv(xid, server, (char *)req, 0, (char **)&resp);
    if (rc)
        goto out;

    *nbytes = le32_to_cpu(resp->DataLength);
    rc = 0;

out:
    cifs_small_buf_release(req);
    return rc;
}

int smb2_handle_write(unsigned int xid, struct cifs_io_parms *io_parms, unsigned int *nbytes,
                      struct kvec *iov, int n_vec) {
    struct smb2_write_request *req;
    struct smb2_write_response *resp;
    int rc = 0;

    req = cifs_buf_get();
    if (!req) {
        return -ENOMEM;
    }

    resp = cifs_buf_get();
    if (!resp) {
        cifs_buf_release(req);
        return -ENOMEM;
    }

    req->hdr.MessageID = cpu_to_le64(xid);
    req->PersistentFileId = io_parms->persistent_fid;
    req->VolatileFileId = io_parms->volatile_fid;
    req->Offset = cpu_to_le64(io_parms->offset);
    req->DataLength = cpu_to_le32(*nbytes);

    rc = cifs_send_recv(io_parms->tcon->ses->server, req, iov, n_vec, resp);
    if (rc) {
        cifs_buf_release(req);
        cifs_buf_release(resp);
        return rc;
    }

    *nbytes = le32_to_cpu(resp->DataLength);

    cifs_buf_release(req);
    cifs_buf_release(resp);
    return 0;
}

int smb2_write(unsigned int xid, struct cifs_io_parms *io_parms, unsigned int *nbytes, struct kvec *iov, int n_vec) {
    struct smb2_write_request *req;
    struct smb2_write_response *resp;
    int rc = 0;
    int bytes_written = 0;

    req = smb2_plain_req_init(SMB2_WRITE, NULL, (struct smb2_hdr **)&req);
    if (!req) {
        return -ENOMEM;
    }

    req->sync_hdr.MsgId = cpu_to_le16(xid);
    req->FileId = io_parms->persistent_fid;
    req->Offset = cpu_to_le64(io_parms->offset);
    req->Length = cpu_to_le32(*nbytes);
    req->Channel = 0;

    rc = cifs_send_recv(io_parms->tcon->ses->server, req, iov, n_vec, CIFS_WRITE_OP, &resp);
    if (rc) {
        cifs_small_buf_release(req);
        return rc;
    }

    if (resp->sync_hdr.Status != 0) {
        rc = -EIO;
    } else {
        bytes_written = le32_to_cpu(resp->Count);
        *nbytes = bytes_written;
    }

    cifs_small_buf_release(req);
    cifs_small_buf_release(resp);

    return rc;
}

int smb2_write(unsigned int xid, struct cifs_io_parms *io_parms, unsigned int *nbytes, struct kvec *iov, int n_vec) {
    struct smb2_write_request *req;
    struct smb2_write_response *resp;
    int rc = 0;
    int resp_buf_type;

    req = smb2_plain_req_init(SMB2_WRITE, io_parms->tcon, NULL);
    if (!req)
        return -ENOMEM;

    req->sync_hdr.MessageId = cpu_to_le64(xid);
    req->FileId = io_parms->pid;
    req->Length = cpu_to_le32(*nbytes);
    req->Offset = cpu_to_le64(io_parms->offset);
    req->Channel = 0;
    req->PersistentFileId = req->FileId;
    req->VolatileFileId = req->FileId;

    rc = cifs_send_recv(io_parms->tcon->ses->server, req,
                        &resp, &resp_buf_type,
                        CIFS_WRITE_OP);

    if (rc) {
        cifs_small_free_response(resp);
        return rc;
    }

    *nbytes = le32_to_cpu(resp->DataLength);

    cifs_small_free_response(resp);

    return rc;
}
